package lk.ac.sliit.ridelink.ride.infrastructure.persistence.mapper;
import lk.ac.sliit.ridelink.ride.domain.model.Ride; import lk.ac.sliit.ridelink.ride.infrastructure.persistence.entity.RideJpaEntity;
public final class RidePersistenceMapper {private RidePersistenceMapper(){} public static Ride domain(RideJpaEntity e){return new Ride(e.getId(),e.getPassengerId(),e.getDriverId(),e.getDriverProfileId(),e.getVehicleId(),e.getPickupName(),e.getDestinationName(),e.getServiceArea(),e.getSimulatedDistanceKm(),e.getVehicleType(),e.getEstimatedFare(),e.getFinalFare(),e.getStatus(),e.getRequestedAt(),e.getAssignedAt(),e.getAcceptedAt(),e.getStartedAt(),e.getCompletedAt(),e.getCancelledAt(),e.getCancellationReason(),e.getDriverSyncStatus(),e.getCreatedAt(),e.getUpdatedAt(),e.getVersion());} public static RideJpaEntity entity(Ride r){RideJpaEntity e=new RideJpaEntity();e.setId(r.getId());e.setPassengerId(r.getPassengerId());e.setDriverId(r.getDriverId());e.setDriverProfileId(r.getDriverProfileId());e.setVehicleId(r.getVehicleId());e.setPickupName(r.getPickupName());e.setDestinationName(r.getDestinationName());e.setServiceArea(r.getServiceArea());e.setSimulatedDistanceKm(r.getSimulatedDistanceKm());e.setVehicleType(r.getVehicleType());e.setEstimatedFare(r.getEstimatedFare());e.setFinalFare(r.getFinalFare());e.setStatus(r.getStatus());e.setRequestedAt(r.getRequestedAt());e.setAssignedAt(r.getAssignedAt());e.setAcceptedAt(r.getAcceptedAt());e.setStartedAt(r.getStartedAt());e.setCompletedAt(r.getCompletedAt());e.setCancelledAt(r.getCancelledAt());e.setCancellationReason(r.getCancellationReason());e.setDriverSyncStatus(r.getDriverSyncStatus());e.setCreatedAt(r.getCreatedAt());e.setUpdatedAt(r.getUpdatedAt());e.setVersion(r.getVersion());return e;} }
